import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(new URL("../../../../frontend/package.json", import.meta.url));
const { build } = require("esbuild");
const source = new URL("../../../../frontend/src/features/project-canvas/documents/intelligent-ui/scope-definition.ts", import.meta.url);
const result = await build({ entryPoints: [fileURLToPath(source)], bundle: true, write: false, format: "esm", platform: "node", target: "es2022", logLevel: "silent" });
const { createScopeDefinitionCache } = await import(`data:text/javascript;base64,${Buffer.from(result.outputFiles[0].text).toString("base64")}`);
const cache = createScopeDefinitionCache();
const block = { type: "uiScope", attrs: { blockId: "a", initial: { amount: 2 }, computed: { doubled: { op: "mul", args: [{ op: "state", name: "amount" }, { op: "literal", value: 2 }] } } } };
const plan = cache.compile(block);
assert.equal(cache.compile(structuredClone(block)), plan);
assert.deepEqual(plan.plans.doubled.dependencies, ["state.amount"]);
assert.throws(() => { plan.computed.doubled.op = "div"; }, TypeError);
assert.throws(() => { plan.plans.doubled.dependencies.push("data.secret"); }, TypeError);
block.attrs.initial.amount = 3;
assert.equal(plan.defaults.amount, 2);
assert.notEqual(cache.compile(block), plan);
assert.notEqual(createScopeDefinitionCache().compile(block), cache.compile(block), "different documents own separate caches");
assert.throws(() => cache.compile({ ...block, attrs: { ...block.attrs, catalogVersion: 99 } }), /catalog.version/);
assert.throws(() => cache.compile({ ...block, attrs: { ...block.attrs, computed: { doubled: undefined } } }), /value.json/);
const current = cache.compile(block);
cache.clear();
assert.notEqual(cache.compile(block), current, "document disposal drops cached plans");
const beforeEviction = cache.compile(block);
for (let index = 0; index < 130; index++) cache.compile({ type: "uiScope", attrs: { blockId: `scope-${index}`, initial: {} } });
assert.notEqual(cache.compile(block), beforeEviction, "entry budget evicts old plans");
const large = (index) => ({ type: "uiScope", attrs: { blockId: `large-${index}`, initial: {}, computed: { data: { op: "literal", value: Array.from({ length: 6 }, () => "x".repeat(50000)) } } } });
const firstLarge = cache.compile(large(0));
for (let index = 1; index < 9; index++) cache.compile(large(index));
assert.notEqual(cache.compile(large(0)), firstLarge, "byte accounting evicts before entry bound");
console.log("scope definition cache: dependencies, immutability, document isolation, versions, invalid input, disposal and count/byte eviction passed");
